      pt: ["'Cidade das flores' da Islândia", "Localizada sobre uma zona termal ativa", "Exposição sobre sismos no centro da cidade", "Ponto de partida para caminhadas até Reykjadalur"],
      fr: ["'Ville des fleurs' d'Islande", "Située au-dessus d'une zone thermale active", "Exposition sur les séismes au centre-ville", "Point de départ pour des randonnées vers Reykjadalur"],
