      pt: "Seyðisfjörður é uma cidade de cariz artístico nos fiordes orientais da Islândia. É famosa pelas suas casas de madeira coloridas e como ponto de acostagem do ferry internacional vindo da Europa.",
      fr: "Seyðisfjörður est une ville à l'esprit artistique située dans les fjords de l'Est de l'Islande. Elle est célèbre pour ses maisons en bois colorées et comme point d'attache du ferry international en provenance d'Europe.",
