      es: ["En Snæfellsnes", "Puerto histórico", "Procesamiento de pescado", "Proximidad al Snæfellsjökull"],
      pt: ["Em Snæfellsnes", "Porto histórico", "Processamento de peixe", "Proximidade ao Snæfellsjökull"],
