      es: ["En la desembocadura del Blanda", "Región de Húnavatnssýsla", "Centro comercial", "Río rico en salmón"],
      pt: ["Na foz do Blanda", "Região de Húnavatnssýsla", "Centro comercial", "Rio rico em salmão"],
