      de: ["Blönduós erhielt im Jahr 1988 offiziell das Stadtrecht.", "Der Fluss Blanda ist einer der wasserreichsten Lachsflüsse Islands.", "Die moderne Kirche wurde vom Architekten Maggi Jónsson entworfen.", "Das Textilmuseum ist das einzige seiner Art in ganz Island.", "Die Einwohnerzahl der Gemeinde liegt bei etwa 900 Personen.", "Der Ort liegt direkt an der isländischen Ringstraße (Route 1)."],
      hu: ["Blönduós 1988-ban kapta meg hivatalosan a városi rangot.", "A Blanda folyó Izland egyik legbővizűbb lazacos folyója.", "A modern templomot Maggi Jónsson építész tervezte.", "A város Textilmúzeuma az egyetlen ilyen jellegű intézmény Izlandon.", "A település lakossága körülbelül 900 főt számlál.", "Az 1-es főút (Ring Road) közvetlenül áthalad a városon."],
