      es: ["Antiguo asentamiento", "Skagafjörður", "Centro de emigración", "Puerto histórico"],
      pt: ["Povoamento antigo", "Skagafjörður", "Centro de emigração", "Porto histórico"],
      fr: ["Ancien établissement", "Skagafjörður", "Centre de l'émigration", "Port historique"],
