      ro: ["Biserica din Kaldrananes a fost ridicată în anul 1851 din lemn.", "Regiunea Strandir este celebră în Islanda pentru istoria sa legată de vrăjitorie.", "Lemnul de plută din Siberia a fost principala resursă de construcție timp de secole.", "Bjarnarfjörður este un loc excelent pentru observarea focilor în mediul lor natural.", "Localitatea se află pe unul dintre cele mai izolate drumuri din Westfjords.", "În interiorul bisericii se află o piesă de altar valoroasă din secolul al XVII-lea."],
      en: ["The church at Kaldrananes was constructed from timber in 1851.", "The Strandir region is famous in Iceland for its history of witchcraft and sorcery.", "Siberian driftwood has been an essential resource for this region for centuries.", "Bjarnarfjörður provides excellent opportunities for observing seals along the shore.", "Kaldrananes is situated along one of the most remote road stretches in the Westfjords.", "The church houses a valuable altarpiece dating back to the 17th century."],
      es: ["La iglesia de Kaldrananes fue construida en madera en 1851.", "La región de Strandir es famosa en Islandia por su historia de brujería.", "La madera de deriva siberiana ha sido un recurso importante en estas costas durante siglos.", "El Bjarnarfjörður ofrece condiciones ideales para la observación de focas.", "Kaldrananes se encuentra en una de las conexiones de carretera más remotas de los Fiordos del Oeste.", "La iglesia alberga un valioso retablo del siglo XVII."],
      pt: ["A igreja de Kaldrananes foi construída em madeira em 1851.", "A região de Strandir é famosa na Islândia pela sua história de feitiçaria.", "A madeira flutuante siberiana tem sido um recurso importante nestas costas há séculos.", "O Bjarnarfjörður oferece condições ideais para a observação de focas.", "Kaldrananes situa-se numa das ligações rodoviárias mais remotas dos Fiordes do Oeste.", "A igreja abriga um valioso painel de altar do século XVII."],
      fr: ["L'église de Kaldrananes a été construite en bois en 1851.", "La région de Strandir est célèbre en Islande pour son histoire de sorcellerie.", "Le bois de dérive sibérien est une ressource importante sur ces côtes depuis des siècles.", "Le Bjarnarfjörður offre des conditions idéales pour l'observation des phoques.", "Kaldrananes se trouve sur l'une des routes les plus isolées des Westfjords.", "L'église abrite un précieux tableau d'autel du XVIIe siècle."],
